import { NextRequest } from "next/server";
import { z } from "zod";
import {
  DEFAULT_TARGETS,
  TARGETS,
  buildPackages,
  buildUpdate,
  distPath,
  listArtifacts,
  listManifests,
  planUpdate,
  type Target,
} from "@/lib/package";
import { isPackaged } from "@/lib/secrets";
import type { IngestProgress } from "@/lib/types";
import pkg from "../../../../package.json";

export const dynamic = "force-dynamic";
/**
 * Assembling a package downloads a Node runtime and compresses ~100 MB — or
 * some 650 MB when the sources and their dependencies ride along.
 */
export const maxDuration = 3600;

/**
 * Building the shareable copy.
 *
 * The endpoint writes files and spawns a build, so like the settings it answers
 * only on a loopback Host — the app has no login because it is only ever meant
 * to be reachable from the machine it runs on.
 */
/**
 * A shared copy has no business building packages.
 *
 * Hiding the panel is enough for the UI, but the endpoint would still be there
 * — and on the receiving end it can only download a Node runtime and overwrite
 * the install it is running from.
 */
function refuseInPackage(): Response | null {
  return isPackaged()
    ? Response.json({ error: "Balíčky se skládají jen ve zdrojovém projektu." }, { status: 403 })
    : null;
}

function isLoopback(req: NextRequest): boolean {
  const name = (req.headers.get("host") ?? "")
    .toLowerCase()
    .replace(/:\d+$/, "")
    .replace(/^\[|\]$/g, "");
  return name === "localhost" || name === "127.0.0.1" || name === "::1";
}

export async function GET(req: NextRequest) {
  const refused = refuseInPackage();
  if (refused) return refused;
  if (!isLoopback(req)) return Response.json({ error: "Jen z localhostu" }, { status: 403 });

  const manifests = listManifests();
  const from = req.nextUrl.searchParams.get("from");
  const to = req.nextUrl.searchParams.get("to");

  let plan = null;
  if (from && to) {
    try {
      plan = planUpdate(from, to);
    } catch (e) {
      plan = { error: (e as Error).message };
    }
  }

  return Response.json({
    version: (pkg as { version: string }).version,
    dist: distPath(),
    targets: Object.entries(TARGETS).map(([id, t]) => ({
      id,
      label: t.label,
      default: DEFAULT_TARGETS.includes(id as Target),
    })),
    manifests,
    artifacts: listArtifacts(),
    plan,
  });
}

const Body = z.discriminatedUnion("mode", [
  z.object({
    mode: z.literal("package"),
    targets: z.array(z.enum(Object.keys(TARGETS) as [Target, ...Target[]])).min(1),
    version: z
      .string()
      .trim()
      .regex(/^[0-9A-Za-z.\-]{1,32}$/, "Verze smí být jen číslice, písmena, tečka a pomlčka"),
    /** "run" = hotová aplikace, "source" = zdroják, do kterého jde sáhnout. */
    shape: z.enum(["run", "source"]).default("run"),
    includeData: z.boolean().default(false),
    includePrices: z.boolean().default(true),
    includeSecArchive: z.boolean().default(false),
    skipBuild: z.boolean().default(false),
  }),
  z.object({
    mode: z.literal("update"),
    from: z.string().trim().min(1),
    to: z.string().trim().min(1),
  }),
]);

export async function POST(req: NextRequest) {
  const refused = refuseInPackage();
  if (refused) return refused;
  if (!isLoopback(req)) return Response.json({ error: "Jen z localhostu" }, { status: 403 });

  let body: z.infer<typeof Body>;
  try {
    body = Body.parse(await req.json());
  } catch (e) {
    return Response.json(
      { error: `Neplatné zadání: ${(e as Error).message.slice(0, 200)}` },
      { status: 400 },
    );
  }

  const encoder = new TextEncoder();
  const stream = new ReadableStream({
    async start(controller) {
      const send = (p: IngestProgress & { results?: unknown }) =>
        controller.enqueue(encoder.encode(JSON.stringify(p) + "\n"));

      try {
        if (body.mode === "package") {
          for await (const progress of buildPackages(body)) send(progress);
        } else {
          const result = await buildUpdate(body.from, body.to, send);
          send({
            step: "done",
            message: `Hotovo — ${result.file}`,
            pct: 100,
            done: true,
            results: [result],
          });
        }
      } catch (e) {
        send({
          step: "error",
          message: "Balíček se nepodařilo vyrobit",
          pct: 100,
          done: true,
          error: (e as Error).message,
        });
      } finally {
        controller.close();
      }
    },
  });

  return new Response(stream, {
    headers: {
      "Content-Type": "application/x-ndjson; charset=utf-8",
      "Cache-Control": "no-store, no-transform",
    },
  });
}
